#!/usr/bin/env node
import {readFile, readdir, stat, writeFile} from 'node:fs/promises';
import path from 'node:path';
import {fileURLToPath, pathToFileURL} from 'node:url';

const repository = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const marker = 'WEBMUSIC BUNDLED LICENSES';
const trailer = new RegExp(`\\n/\\*! ${marker}\\n[\\s\\S]*?\\n\\*/\\n`, 'g');
const reviewedSnapshots = {
  '@nodable/entities@3.0.0': {
    license: 'MIT',
    repository: 'git+https://github.com/nodable/val-parsers.git',
    file: 'scripts/licenses/nodable-entities-3.0.0-MIT.txt',
  },
};

async function filesUnder(directory) {
  const entries = await readdir(directory, {withFileTypes: true});
  return (await Promise.all(entries.map((entry) => entry.isDirectory()
    ? filesUnder(path.join(directory, entry.name))
    : [path.join(directory, entry.name)]))).flat().sort();
}

async function packageOwner(source) {
  let directory = path.dirname(source);
  while (directory !== path.dirname(directory)) {
    try {
      const manifest = JSON.parse(await readFile(path.join(directory, 'package.json'), 'utf8'));
      if (manifest.name && manifest.version) return {directory, manifest};
    } catch (error) {
      if (error.code !== 'ENOENT' && error.code !== 'ENOTDIR') throw error;
    }
    directory = path.dirname(directory);
  }
  throw new Error(`Cannot identify the package owning bundled source ${source}`);
}

async function licenseRecord(owner) {
  const {directory, manifest} = owner;
  const entries = (await readdir(directory)).sort();
  const licenseFiles = entries.filter((name) => /^(licen[cs]e|copying)(\.[^.]+)?$/i.test(name));
  const noticeFiles = entries.filter((name) => /^notice(\.[^.]+)?$/i.test(name));
  const snapshot = reviewedSnapshots[`${manifest.name}@${manifest.version}`];
  const useSnapshot = !licenseFiles.length && snapshot
    && manifest.license === snapshot.license && manifest.repository?.url === snapshot.repository;
  if ((!licenseFiles.length && !useSnapshot) || typeof manifest.license !== 'string') {
    throw new Error(`${manifest.name}: bundled packages need a license identifier and license text.`);
  }
  const documents = [];
  if (useSnapshot) documents.push(`LICENSE (reviewed upstream snapshot)\n${(await readFile(path.join(repository, snapshot.file), 'utf8')).trim()}`);
  for (const name of [...licenseFiles, ...noticeFiles]) {
    const filename = path.join(directory, name);
    if (!(await stat(filename)).isFile()) throw new Error(`License is not a file: ${filename}`);
    const content = (await readFile(filename, 'utf8')).replace(/\r\n?/g, '\n').trim();
    if (!content || content.includes('*/')) throw new Error(`Cannot embed the license safely: ${filename}`);
    documents.push(`${name}\n${content}`);
  }
  return {
    key: `${manifest.name}@${manifest.version}`,
    text: `${manifest.name}@${manifest.version}\nLicense: ${manifest.license}\n\n${documents.join('\n\n')}`,
  };
}

function noticeText(records) {
  return 'WebMusic bundled dependency notices\n\n'
    + 'These packages are included in the generated JavaScript. Their original\n'
    + 'copyright notices and license terms follow. WebMusic\'s license does not\n'
    + 'replace these terms. Generated by scripts/bundle-notices.mjs.\n\n'
    + records.map((record) => record.text).join('\n\n' + '='.repeat(72) + '\n\n') + '\n';
}

/** Append notices after generated code, preserving every original source-map offset. */
export function attachNotices(code, notices) {
  const clean = code.replace(trailer, '\n');
  const footer = clean.match(/\n\/\/[#@] sourceMappingURL=[^\r\n]*\n?$/)?.[0] ?? '';
  const body = footer ? clean.slice(0, -footer.length) : clean.replace(/\n$/, '');
  return `${body}\n/*! ${marker}\n${notices.trimEnd()}\n*/\n${footer ? footer.slice(1) : ''}`;
}

/** Discover actual bundled owners from source maps; never infer them from dependencies alone. */
export async function processBundleNotices({packageDirectory = path.join(repository, 'packages/score'), check = false} = {}) {
  const dist = path.join(packageDirectory, 'dist');
  const paths = await filesUnder(dist);
  const maps = paths.filter((filename) => /\.(?:js|cjs)\.map$/.test(filename));
  if (!maps.length) throw new Error(`No JavaScript source maps in ${dist}; build the package first.`);
  const ownerCache = new Map();
  const allRecords = new Map();
  const outputs = [];
  for (const filename of maps) {
    const sourceMap = JSON.parse(await readFile(filename, 'utf8'));
    if (!Array.isArray(sourceMap.sources) || sourceMap.sections) throw new Error(`Unsupported source map: ${filename}`);
    const records = new Map();
    for (const source of sourceMap.sources) {
      const fullPath = path.resolve(path.dirname(filename), sourceMap.sourceRoot ?? '', source);
      const owner = await packageOwner(fullPath);
      if (path.resolve(owner.directory) === path.resolve(packageDirectory)) continue;
      if (!ownerCache.has(owner.directory)) ownerCache.set(owner.directory, await licenseRecord(owner));
      const record = ownerCache.get(owner.directory);
      if (allRecords.has(record.key) && allRecords.get(record.key).text !== record.text) {
        throw new Error(`Conflicting license texts for ${record.key}.`);
      }
      records.set(record.key, record);
      allRecords.set(record.key, record);
    }
    if (records.size) {
      const javascript = filename.slice(0, -4);
      const code = await readFile(javascript, 'utf8');
      const ordered = [...records.values()].sort((a, b) => a.key.localeCompare(b.key));
      outputs.push({filename: javascript, content: attachNotices(code, noticeText(ordered))});
    }
  }
  if (!allRecords.size) throw new Error('No bundled dependencies found; check the build and its source maps.');
  outputs.push({
    filename: path.join(dist, 'THIRD_PARTY_NOTICES.txt'),
    content: noticeText([...allRecords.values()].sort((a, b) => a.key.localeCompare(b.key))),
  });
  for (const output of outputs) {
    if (check) {
      let current;
      try { current = await readFile(output.filename, 'utf8'); } catch (error) {
        if (error.code !== 'ENOENT') throw error;
      }
      if (current !== output.content) throw new Error(`Missing or stale bundled notices: ${output.filename}`);
    } else {
      await writeFile(output.filename, output.content);
    }
  }
  return {packages: allRecords.size, bundles: outputs.length - 1};
}

if (process.argv[1] && import.meta.url === pathToFileURL(path.resolve(process.argv[1])).href) {
  const args = process.argv.slice(2);
  if (args.some((arg) => arg !== '--check')) throw new Error('Usage: node scripts/bundle-notices.mjs [--check]');
  const check = args.includes('--check');
  const result = await processBundleNotices({check});
  console.log(`Bundled notices ${check ? 'verified' : 'written'}: ${result.packages} packages in ${result.bundles} bundles.`);
}
